from html.parser import HTMLParser
from pathlib import Path
import json,re,subprocess
text=Path("notebook.html").read_text()
class Audit(HTMLParser):
    def __init__(self):
        super().__init__();self.stack=[];self.ids=set();self.links=[]
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if "id" in a:
            assert a["id"] not in self.ids, "Duplicate anchor: "+a["id"]
            self.ids.add(a["id"])
        if "href" in a:self.links.append(a["href"])
        if tag not in {"br","hr","img","input","meta","link","source","wbr"}:self.stack.append(tag)
    def handle_endtag(self,tag):
        assert self.stack and self.stack.pop()==tag, "Misnested tag: "+tag
audit=Audit();audit.feed(text);assert not audit.stack
for href in audit.links:
    if href.startswith("#"):assert href[1:] in audit.ids,href
    prefix="https://github.com/kbr-/math-research/blob/main/"
    if href.startswith(prefix):
        parts=href[len(prefix):].split("#",1);path=Path(parts[0]);assert path.is_file(),href
        if len(parts)==2:
            assert "id=\""+parts[1]+"\"" in path.read_text(),href
